export const civilYear=y=>y>0?y-1:y;
export const inWindow=(e,year,span)=>civilYear(e.start)<=civilYear(year)+span&&civilYear(e.end)>=civilYear(year)-span;
export function wikipediaURL(value){if(/^https:\/\//.test(value))return value;if(/^[a-z-]+\.wikipedia\.org\/wiki\//.test(value))return 'https://'+value;return 'https://en.wikipedia.org/wiki/'+encodeURIComponent(value.replaceAll(' ','_'));}
export const EMPTY={type:'FeatureCollection',features:[]};
export async function readJSON(url){const r=await fetch(url);if(!r.ok)throw Error(`${r.status} ${url}`);if(url.endsWith('.gz')){const bytes=new Uint8Array(await r.arrayBuffer());if(bytes[0]===31&&bytes[1]===139)return new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).json();return JSON.parse(new TextDecoder().decode(bytes));}return r.json();}
const PALETTE=['#a78254','#76988c','#968791','#9d9a62','#69929e','#967d62','#849773','#718ca9','#ab836e','#80876c','#8a809e','#a39878'];
export function color(name){let h=0;for(const c of name)h=((h<<5)-h+c.charCodeAt(0))|0;return PALETTE[Math.abs(h)%PALETTE.length];}
export function formatYear(y,lang='zh'){return lang==='en'?`${Math.abs(y).toLocaleString('en-US')} ${y<0?'BCE':'CE'}`:`${y<0?'公元前':'公元'} ${Math.abs(y).toLocaleString('en-US')} 年`;}
export function activeRecords(catalog,year,relations=false){if(year===0||year< -3400||year>2024)return [];return catalog.records.filter(r=>r.start<=year&&year<=r.end&&(relations||r.type==='POLITY')).sort((a,b)=>b.area-a.area);}
export function stepYear(year,step){const next=year+step;return year<0&&next>=0?next+1:year>0&&next<=0?next-1:next;}
export function polityName(r,lang){return lang==='en'?r.name:(r.zhName||r.name);}
function grid(){const fs=[];for(let lon=-180;lon<180;lon+=30){const line=[];for(let lat=-80;lat<=80;lat+=2)line.push([lon,lat]);fs.push({type:'Feature',properties:{},geometry:{type:'LineString',coordinates:line}});}for(let lat=-60;lat<=60;lat+=30){const line=[];for(let lon=-180;lon<=180;lon+=2)line.push([lon,lat]);fs.push({type:'Feature',properties:{},geometry:{type:'LineString',coordinates:line}});}return {type:'FeatureCollection',features:fs};}
export class AtlasMap{
 constructor(container,{onPolity,onReady,onError}={}){
  this.map=new maplibregl.Map({container,center:[12,16],zoom:.75,minZoom:.35,maxZoom:7,style:{version:8,sources:{land:{type:'geojson',data:'data/land.geojson'},grid:{type:'geojson',data:grid()},polities:{type:'geojson',data:EMPTY}},layers:[{id:'ocean',type:'background',paint:{'background-color':'#0b1b2b'}},{id:'land',type:'fill',source:'land',paint:{'fill-color':'#2a414a'}},{id:'coast',type:'line',source:'land',paint:{'line-color':'#51616a','line-width':.5}},{id:'grid',type:'line',source:'grid',paint:{'line-color':'#738390','line-opacity':.14,'line-width':.6}},{id:'territories',type:'fill',source:'polities',paint:{'fill-color':['get','color'],'fill-opacity':.73}},{id:'boundary',type:'line',source:'polities',paint:{'line-color':'#ebe0c6','line-width':.65,'line-opacity':.6}},{id:'selection',type:'line',source:'polities',filter:['==','id',''],paint:{'line-color':'#ffd391','line-width':2.8}}]},attributionControl:false});
  this.map.addControl(new maplibregl.NavigationControl({showCompass:false}),'bottom-right');this.map.addControl(new maplibregl.AttributionControl({compact:true,customAttribution:'<a href="https://github.com/Seshat-Global-History-Databank/cliopatria" target="_blank" rel="noopener">Cliopatria / Seshat · CC BY 4.0</a> · <a href="https://www.naturalearthdata.com/" target="_blank" rel="noopener">Natural Earth</a>'}),'bottom-right');
  this.cache=new Map();this.recordMap=new Map();this.labels=[];this.markers=[];this.request=0;this.lang='bi';this.showLabels=true;this.showEvents=true;this.showBorders=true;
  this.ready=new Promise(resolve=>this.map.once('load',()=>{resolve();onReady?.();}));
  this.map.on('click','territories',e=>{if(!this.showBorders)return;const feature=e.features?.[0];if(feature){const r=this.recordMap.get(feature.properties.id);if(r)onPolity?.(r);}});
  this.map.on('mouseenter','territories',()=>this.map.getCanvas().style.cursor='pointer');this.map.on('mouseleave','territories',()=>this.map.getCanvas().style.cursor='');
  this.map.on('error',e=>{if(e.error?.message?.includes('Failed to fetch'))onError?.(e.error);});
  this.map.on('moveend',()=>this.refreshLabels());
 }
 async shard(file){if(!this.cache.has(file)){const p=readJSON('data/'+file+'.gz').catch(e=>{this.cache.delete(file);throw e;});this.cache.set(file,p);}return this.cache.get(file);}
 async setYear(catalog,year,lang=this.lang){this.lang=lang;this.year=year;const seq=++this.request;await this.ready;const records=activeRecords(catalog,year);const files=[...new Set(records.map(r=>catalog.geometryIndex[r.geometryId]))];const results=new Map();await Promise.all(files.map(async file=>results.set(file,await this.shard(file))));if(seq!==this.request)return false;this.recordMap=new Map(records.map(r=>[r.id,r]));this.active=records;const features=records.map(r=>({type:'Feature',properties:{id:r.id,name:r.name,color:color(r.name)},geometry:results.get(catalog.geometryIndex[r.geometryId])[r.geometryId]}));this.map.getSource('polities').setData({type:'FeatureCollection',features});this.refreshLabels();return records.length;}
 refreshLabels(){this.labels.forEach(m=>m.remove());this.labels=[];if(!this.active||!this.showLabels||!this.showBorders)return;const bounds=this.map.getBounds();const zoom=this.map.getZoom();const candidates=this.active.filter(r=>r.center&&bounds.contains(r.center)).sort((a,b)=>b.area-a.area);const placed=[];for(const r of candidates){if(this.labels.length>=Math.min(65,18+Math.floor(zoom)*10))break;if(r.area<2000/(zoom||1))continue;const p=this.map.project(r.center);if(p.x<300&&p.y<140)continue;if(placed.some(v=>Math.abs(v.x-p.x)<105&&Math.abs(v.y-p.y)<35))continue;placed.push(p);const el=document.createElement('div');el.className='polity-label';el.textContent=polityName(r,this.lang);if(this.lang==='bi'&&r.zhName){const s=document.createElement('span');s.textContent=r.name;el.append(s);}const marker=new maplibregl.Marker({element:el}).setLngLat(r.center).addTo(this.map);this.labels.push(marker);}}
 setEvents(events,lang,onClick,selected){this.markers.forEach(m=>m.remove());this.markers=[];if(!this.showEvents)return;for(const event of events.slice(0,400)){const el=document.createElement('button');el.className='event-marker'+(event.id===selected?' selected':'');el.style.setProperty('--cat',event.color||'#e7b867');el.title=lang==='en'?event.title.en:event.title.zh;el.setAttribute('aria-label',el.title);el.addEventListener('click',e=>{e.stopPropagation();onClick(event);});this.markers.push(new maplibregl.Marker({element:el}).setLngLat([event.lon,event.lat]).addTo(this.map));}}
 toggleBorders(v){this.showBorders=v;['territories','boundary','selection'].forEach(id=>this.map.setLayoutProperty(id,'visibility',v?'visible':'none'));this.refreshLabels();}
 selectPolity(r){this.map.setFilter('selection',['==','id',r.id]);}
 fly(lon,lat,zoom=3){this.map.flyTo({center:[lon,lat],zoom:Math.min(5,zoom),duration:900,essential:false});}
 reset(){this.map.flyTo({center:[12,16],zoom:.75,duration:800});}
 projection(globe){this.map.setProjection({type:globe?'globe':'mercator'});}
 destroy(){this.markers.forEach(m=>m.remove());this.labels.forEach(m=>m.remove());this.map.remove();}
}
